import{z as s,x as l,o as B,c as h,q as n,j as o,D as a,d as E,s as i,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"逆向选择的深化","description":"","frontmatter":{"title":"逆向选择的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ct-adverse-selection-deep.md","filePath":"econ/ct-adverse-selection-deep.md","lastUpdated":1791413859000}'),d={name:"econ/ct-adverse-selection-deep.md"};function c(p,e,C,m,D,u){const r=l("Mermaid");return B(),h("div",null,[e[2]||(e[2]=n('<h1 id="逆向选择的深化" tabindex="-1">逆向选择的深化 <a class="header-anchor" href="#逆向选择的深化" aria-label="Permalink to &quot;逆向选择的深化&quot;">​</a></h1><div class="epigraph"><p>信息租金是让高效率者说真话的价格；压低低效率者的产量，是付这笔账的钱。</p><footer>—— 据 Mirrlees, Review of Economic Studies, 1971；Mussa and Rosen, Quarterly Journal of Economics, 1978 整理</footer></div><p><a href="/econ/ct-moral-hazard-deep">上一课</a>把隐藏行动的合同形状钉在一阶方法与两步实施上。本课换符号：类型签约前已定，不知情者出菜单让类型对号。<a href="/econ/screening-rent">筛选与信息租金</a>给了两类型直觉——低类型数量扭曲、高类型不扭曲、租金留给高类型；<a href="/econ/rs-unraveling">Rothschild–Stiglitz 崩溃</a>警告竞争下均衡可以不存在。本课把两类型直觉升级成连续类型的一般机器，再检查机器在竞争、多维与激励方向翻转处的断点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两类型直觉缺三件事。第一，连续类型的解怎么写：哪条 IC 绑定、租金落在哪一段、扭曲沿类型如何分布，需要一个不逐对比对的算法。第二，扭曲的位置由什么决定：直觉只说「扭曲低类型」，连续世界里「低」到什么程度、向哪个方向扭曲，得由类型分布的形状给出。第三，机器的前提清单：单交叉、类型一维、激励方向单一——每一项在应用里都可能断，断点处老结论会安静失效，这才是最危险的错。</p><p><span class="marginnote">术语翻译：「信息租金」就是让强类型不说谎的封口费——委托人必须给高效率类型留一块额外好处，他才不肯假装低效率去蹭便宜合同；真正昂贵的还不止这笔租金，而是为堵住说谎所做的产量扭曲。</span></p><h3 id="包络把搜索删掉" tabindex="-1">包络把搜索删掉 <a class="header-anchor" href="#包络把搜索删掉" aria-label="Permalink to &quot;包络把搜索删掉&quot;">​</a></h3><p>一维类型 \\(\\theta\\in[\\underline\\theta,\\bar\\theta]\\)，配置 \\(q(\\theta)\\)，支付 \\(t(\\theta)\\)。单交叉下，IC 等价于 \\(q\\) 非降，且代理人效用沿包络 \\(U(\\theta)=U(\\underline\\theta)+\\int_{\\underline\\theta}^{\\theta}q(s)\\,ds\\) 演化：租金被积分钉死，只剩底线 \\(U(\\underline\\theta)\\) 一个自由量。委托人分部积分后，目标里的租金项折进虚拟剩余 \\(J(\\theta)=\\theta-\\frac{1-F(\\theta)}{f(\\theta)}\\)——与<a href="/econ/myerson-virtual-value">迈尔森虚拟价值</a>同一构造，拍卖是它的卖方特例。正则区间内 \\(q\\) 由 \\(J(\\theta)=\\text{边际成本}\\) 决定，低于完全信息水平；顶端 \\(J(\\bar\\theta)=\\bar\\theta\\) 无扭曲，底端扭曲最重乃至排除。<a href="/econ/mirrlees-optimal-tax">最优所得税</a>是同一台机器换福利权重运转，连顶端税率与 Pareto 尾的关系都同构。</p><p><span class="marginnote">顶端无扭曲不是仁慈，是最便宜的防伪：高类型只要模仿低合同就能吞掉租金，任何给顶端的扭曲都要用更高的租金去赎。把全部扭曲推到底端，是租金—效率权衡的角点解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机器上街前过三道检查。其一，单交叉在不在：偏好只交叉一次，包络才等价于 IC；保险里风险与财富两维交叉，税收里技能与劳动供给弹性交叉，都可能破坏。其二，激励方向：当类型同时移动保留效用的方向——比如成本参数也影响外部机会——可能出现反向激励，租金留给低类型、扭曲从中间断开，Lewis 与 Sappington 在 1989 年把它命名为对冲激励。其三，维数：两维以上类型，IC 是偏微分不等式组，单调性不再刻画可实施集，Rochet 与 Choné 在 1998 年给出的解法是熨平与清扫，一般没有闭式，数值是常态。</p><p><span class="marginnote">为什么重要：单交叉一旦不成立，包络条件就不再等价于激励相容，「积分钉死租金」的整套算法会安静失效——不会报错，而是继续给你一个错误的解。保险里风险与财富两维交叉正是典型翻车点。</span></p>',12)),(B(),o(A,null,{default:a(()=>[i(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MENU%5B%22%E5%87%BA%E8%8F%9C%E5%8D%95%20q(%CE%B8)%2C%20t(%CE%B8)%22%5D%20--%3E%20ENV%5B%22%E5%8D%95%E4%BA%A4%E5%8F%89%20%2B%20%E5%8C%85%E7%BB%9C%EF%BC%9A%E7%A7%9F%E9%87%91%E7%A7%AF%E5%88%86%E9%92%89%E6%AD%BB%22%5D%0A%20%20ENV%20--%3E%20J%5B%22%E8%99%9A%E6%8B%9F%E5%89%A9%E4%BD%99%20J(%CE%B8)%20%E5%AE%9A%E6%89%AD%E6%9B%B2%22%5D%0A%20%20J%20--%3E%20CHK%7B%22%E5%89%8D%E6%8F%90%E6%A3%80%E6%9F%A5%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%8D%95%E4%BA%A4%E5%8F%89%E5%A4%B1%E8%B4%A5%22%7C%20MC%5B%22IC%20%E4%B8%8D%E5%86%8D%E7%AD%89%E4%BB%B7%E5%8D%95%E8%B0%83%EF%BC%8C%E7%9B%B4%E6%8E%A5%E8%A7%A3%E4%B8%8D%E7%AD%89%E5%BC%8F%E7%BB%84%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%BF%80%E5%8A%B1%E6%96%B9%E5%90%91%E7%BF%BB%E8%BD%AC%22%7C%20CVI%5B%22%E5%AF%B9%E5%86%B2%E6%BF%80%E5%8A%B1%EF%BC%9A%E7%A7%9F%E9%87%91%E6%8D%A2%E8%BE%B9%22%5D%0A%20%20CHK%20--%3E%7C%22%E7%B1%BB%E5%9E%8B%E5%A4%9A%E7%BB%B4%22%7C%20MD%5B%22%E7%86%A8%E5%B9%B3%E4%B8%8E%E6%B8%85%E6%89%AB%EF%BC%8C%E6%95%B0%E5%80%BC%E6%B1%82%E8%A7%A3%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%22%7C%20OK%5B%22%E9%A1%B6%E7%AB%AF%E6%97%A0%E6%89%AD%E6%9B%B2%EF%BC%8C%E5%BA%95%E7%AB%AF%E9%87%8D%E6%89%AD%E6%9B%B2%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,[E("机制是同一个：合同必须可验证地不可模仿，扭曲就是防伪标记。Mussa 与 Rosen 在 1978 年把它写成品级歧视——垄断者给低端产品压质量，不是成本考虑，而是防止高支付意愿者滑进低价合同；「自毁芯片」式的产品线分层是这条定理的日常形态。金融市场同一台戏："),t("a",{href:"/econ/pecking-order"},"优序融资"),E("里 Myers 与 Majluf 让外部股权因为逆向选择折价，内部资金与安全债排在前面，融资顺序本身就是市场自发的筛选菜单。")],-1)),(B(),o(A,null,{default:a(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%AB%98%E7%B1%BB%E5%9E%8B%EF%BC%9A%E6%95%88%E7%8E%87%20%CE%B8%20%E9%AB%98%22%5D%20--%3E%20M%5B%22%E8%8B%A5%E6%A8%A1%E4%BB%BF%E4%BD%8E%E7%B1%BB%E5%9E%8B%E5%90%88%E5%90%8C%EF%BC%8C%E5%8F%AF%E5%90%9E%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%22%5D%0A%20%20M%20--%3E%20D%5B%22%E5%A7%94%E6%89%98%E4%BA%BA%E5%8E%8B%E4%BD%8E%E4%BD%8E%E5%90%88%E5%90%8C%E7%9A%84%20q%20%2F%20%E8%B4%A8%E9%87%8F%EF%BC%9A%E9%98%B2%E4%BC%AA%E6%A0%87%E8%AE%B0%22%5D%0A%20%20L%5B%22%E4%BD%8E%E7%B1%BB%E5%9E%8B%EF%BC%9A%E6%89%AD%E6%9B%B2%E6%9C%80%E9%87%8D%E4%B9%83%E8%87%B3%E8%A2%AB%E6%8E%92%E9%99%A4%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20P%5B%22%E6%A8%A1%E4%BB%BF%E7%9A%84%E6%B2%B9%E6%B0%B4%E8%A2%AB%E6%89%AD%E6%9B%B2%E5%89%8A%E6%8E%89%22%5D%0A%20%20P%20--%3E%20T%5B%22%E9%AB%98%E7%B1%BB%E5%9E%8B%E5%AE%89%E4%BA%8E%E8%87%AA%E5%B7%B1%E7%9A%84%E5%90%88%E5%90%8C%EF%BC%9A%E8%AF%B4%E7%9C%9F%E8%AF%9D%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=n('<p><span class="marginnote">数字实例：类型均匀分布在 \\([0,1]\\) 时，\\(\\frac{1-F(\\theta)}{f(\\theta)}=1-\\theta\\)，虚拟剩余 \\(J(\\theta)=2\\theta-1\\)；于是只有 \\(\\theta\\gt 1/2\\) 的类型被服务，产量还一律向下压——均匀分布把「排除与扭曲」的算术摆到了明面上。</span></p><p>竞争侧的断点在<a href="/econ/rs-unraveling">RS 崩溃</a>里已经见过：混同必被撇脂，分离可能被挖角，均衡可以不存在。修补的口径是把「别人会怎么反应」写进均衡定义：Wilson 在 1977 年让合同作者预见到后续进入，Riley 在 1979 年把反应路径钉进均衡概念。修补之后筛选手印仍在——低风险者拿高免赔额合同补贴自己，高风险者被挤到贵而全的合同上；监管若一刀切禁掉类型定价，等于拆掉分离机制，市场向混同和退出滑落。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>双边都有私人信息时，<a href="/econ/myerson-satterthwaite">Myerson–Satterthwaite</a> 已经钉死：IC、参与、预算平衡与事后有效不可兼得，本课不重证。动态版是另一条裂缝——今天的配置泄露类型，明天的菜单会报复，合同因此想装傻，那是下一课的棘轮。耗散对比与 PBE 精炼的武器库，<a href="/econ/spence-signaling">信号发送</a>与<a href="/econ/pooling-separating">混同分离</a>已备，不再展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单交叉加包络把连续筛选收成：\\(q\\) 单调、租金积分钉死、只剩底线一个常数。</li><li>扭曲沿虚拟剩余 \\(J(\\theta)\\) 分布：顶端无扭曲，底端最重，同构于最优税与最优拍卖。</li><li>单交叉失败、激励方向翻转、多维类型是机器的三个断点，分别要不等式组、对冲激励与数值熨平。</li><li>质量歧视与优序融资是同一防伪逻辑在产品与融资上的形态。</li><li>竞争筛选的存在性靠预期反应与反应均衡修补，类型定价被禁会推向混同。</li><li>出处：Mirrlees, <em>RES</em> 1971；Rothschild and Stiglitz, <em>QJE</em> 1976；Mussa and Rosen, <em>QJE</em> 1978；Wilson, <em>JET</em> 1977；Riley, <em>REStud</em> 1979；Rochet and Choné, <em>Econometrica</em> 1998。</li></ul>',6))])}const _=s(d,[["render",c]]);export{f as __pageData,_ as default};
